/* ================= ADMIN WORKSPACE (staff + admin) =================
   A1 core: state, helpers, slide-over panel, undo toast, order status engine, sample data */
const AS={o:{tab:'active',range:'all',type:'all',sort:'new',q:'',view:'list',n:15,sel:[]},t:{tab:'active',range:'all',sort:'new',q:'',view:'list',n:15,sel:[]},
inv:{tab:'all',cat:'All',sort:'name',q:'',view:'cards',n:30},po:{tab:'restock',q:'',n:20},sup:{q:''},rec:{tab:'all',range:'all',q:'',n:25},usr:{tab:'all',q:''},cfm:''};
const SK={orders:'o',trade:'t',inventory:'inv',purchasing:'po',suppliers:'sup',records:'rec',users:'usr'},WV={orders:'o',trade:'t'},KIND={o:'retail',t:'trade'};
const SC={Pending:'warn',Processing:'info',Ready:'ok',Completed:'mute',Cancelled:'bad',Ordered:'info',Received:'ok'},
NXT={Pending:'Processing',Processing:'Ready',Ready:'Completed'},ACT=['Pending','Processing','Ready'],
LBL={Pending:'Order placed',Processing:'Started processing',Ready:'Marked ready',Completed:'Completed',Cancelled:'Cancelled'},
SRCH='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/></svg>',
set_=(id,h)=>{const e=document.getElementById(id);if(e)e.innerHTML=h},
day0=t=>{const d=new Date(t);d.setHours(0,0,0,0);return +d},
inR=(t,r)=>r==='all'||t>=(r==='today'?day0(Date.now()):Date.now()-(+r)*864e5),
ago=t=>{const m=Math.round((Date.now()-t)/6e4);if(m<1)return 'Just now';if(m<60)return m+' min ago';const h=Math.round(m/60);if(h<24)return h+' hr ago';const d=Math.round(h/24);return d===1?'Yesterday':d<30?d+' days ago':fmt(t)},
tm2=t=>new Date(t).toLocaleString('en-PH',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}),
dayLbl=t=>{const d=day0(Date.now()),x=day0(t);return x===d?'Today':x===d-864e5?'Yesterday':fmt(t)},
units=o=>o.items.reduce((a,i)=>a+i.q,0),pl=(n,w)=>n+' '+w+(n===1?'':'s'),
pill=s=>`<span class="pill ${SC[s]||'mute'}">${esc(s)}</span>`,
adph=(t,s,a)=>`<div class="ph ad-ph"><div><h1>${t}</h1><p class="mute">${s}</p></div>${a?`<div class="ad-pa">${a}</div>`:''}</div>`,
fld=(n,l,t,a)=>`<label class="ad-f">${l}<input name="${n}" type="${t||'text'}" required ${a||''}></label>`,
sel=(n,l,o,a)=>`<label class="ad-f">${l}<select name="${n}" required ${a||''}>${o}</select></label>`,
thm=(o,m=3)=>`${o.items.slice(0,m).map(i=>`<span class="tile mini">${prod(i.p)?pic(prod(i.p)):'📦'}</span>`).join('')}${o.items.length>m?`<span class="ad-more">+${o.items.length-m}</span>`:''}`,
lastPO=id=>S.purchases.filter(x=>x.p===id&&x.status!=='Cancelled').sort((a,b)=>b.ts-a.ts)[0],
incoming=id=>S.purchases.filter(x=>x.p===id&&x.status==='Ordered').reduce((a,x)=>a+x.q,0),
sugg=p=>Math.max(p.min*3-p.stock,p.min);

/* ---------- undo toast ---------- */
const adtoast=document.createElement('div');adtoast.id='adtoast';adtoast.setAttribute('role','status');adtoast.setAttribute('aria-live','polite');document.body.appendChild(adtoast);
let adT,adU=null;
function adNote(m,undo){adU=undo||null;adtoast.innerHTML=`<span>${esc(m)}</span>${undo?'<button type="button" data-undo>Undo</button>':''}`;adtoast.classList.add('on');clearTimeout(adT);adT=setTimeout(()=>adtoast.classList.remove('on'),undo?7000:3600)}

/* ---------- slide-over panel (DR.<type> returns {k,title,body,foot}) ---------- */
const DR={};let drw=null,drOp=null;
const adw=document.createElement('div');adw.id='adw';adw.hidden=true;
adw.innerHTML='<div class="adw-bg" data-close></div><aside class="adw-panel" role="dialog" aria-modal="true" aria-labelledby="adw-t"><div id="adw-body"></div></aside>';document.body.appendChild(adw);
function adOpen(t,id,ex,from){drw={t,id:id||'',ex:ex||{},prev:from?drw:null};AS.cfm='';
if(adw.hidden){drOp=document.activeElement;document.documentElement.style.setProperty('--sbw',(innerWidth-document.documentElement.clientWidth)+'px');adw.hidden=false;document.documentElement.classList.add('adw-lock')}
requestAnimationFrame(()=>requestAnimationFrame(()=>drw&&adw.classList.add('on')));adDraw(true)}
function adClose(now){if(adw.hidden)return;drw=null;AS.cfm='';adw.classList.remove('on');const fin=()=>{if(!drw){adw.hidden=true;document.documentElement.classList.remove('adw-lock');document.documentElement.style.removeProperty('--sbw')}};now?fin():setTimeout(fin,260);if(drOp&&drOp.isConnected&&drOp.focus)drOp.focus({preventScroll:true});drOp=null}
function adBack(){if(drw&&drw.prev){drw=drw.prev;AS.cfm='';adDraw(true)}}
function adDraw(fresh){if(!drw)return;const f=DR[drw.t],r=f&&f(drw.id,drw.ex);if(!r){adClose(true);return}
const sc=adw.querySelector('.adw-scroll'),y=sc&&!fresh?sc.scrollTop:0;
document.getElementById('adw-body').innerHTML=`<div class="adw-top">${drw.prev?'<button class="adw-back" onclick="adBack()">← Back</button>':''}<button class="adw-x" aria-label="Close panel" data-close>✕</button></div><div class="adw-scroll"><div><div class="adw-k">${r.k}</div><div class="adw-title" id="adw-t">${r.title}</div></div>${r.body}</div><div class="adw-foot">${r.foot||''}</div>`;
const n=adw.querySelector('.adw-scroll');if(n)n.scrollTop=y;
if(fresh){const x=adw.querySelector('.adw-x');x&&x.focus({preventScroll:true})}adPoSum();adTrSum()}
function adSync(){const r=me().role;if(r!=='staff'&&r!=='admin'){adClose(true);document.body.classList.remove('bulk')}adBulk()}

/* ---------- order status engine (handles stock both ways, keeps a history) ---------- */
function adSet(pairs,undo){let n=0,bad=0;const back=[];
pairs.forEach(([id,to])=>{const o=S.orders.find(x=>x.id===id);if(!o||o.status===to)return;const from=o.status;
if(to==='Cancelled'&&!o.smp)o.items.forEach(i=>prod(i.p)&&(prod(i.p).stock+=i.q));
if(from==='Cancelled'&&!o.smp){if(o.items.some(i=>prod(i.p)&&prod(i.p).stock<i.q)){bad++;return}o.items.forEach(i=>prod(i.p)&&(prod(i.p).stock-=i.q))}
if(!o.log)o.log=[{s:'Pending',ts:o.ts}];o.log.push(undo?{s:to,ts:Date.now(),u:from}:{s:to,ts:Date.now()});o.status=to;back.push([id,from]);n++});
return{n,bad,back}}
function adMove(pairs){const r=adSet(pairs);if(!r.n){adNote(r.bad?'Not enough stock to reopen that order.':'Nothing to change.');return}
save();[AS.o,AS.t].forEach(s=>s.sel=s.sel.filter(x=>!pairs.some(p=>p[0]===x)));AS.cfm='';const tos=[...new Set(pairs.map(p=>p[1]))];
const msg=r.n===1?`${pairs[0][0]} moved to ${pairs[0][1]}.`:tos.length===1?`${r.n} orders moved to ${tos[0]}.`:`${r.n} orders moved to their next step.`;
adNote(msg,()=>{const u=adSet(r.back,true);save();adRefresh();adNote(u.bad?'Could not restore every order (stock).':'Change undone.')});adRefresh()}
const adNext=id=>{const o=S.orders.find(x=>x.id===id);o&&NXT[o.status]&&adMove([[id,NXT[o.status]]])},adCancel=id=>adMove([[id,'Cancelled']]);

/* ---------- refresh: re-draw only the live regions of the current page ---------- */
const PG={};
function adRefresh(){const p=PG[view];p&&p.refresh&&p.refresh();adDraw();adBulk()}
const DN={o:15,t:15,inv:30,po:20,rec:25};
function adJump(pg,patch){adClose(true);const k=SK[pg],s=AS[k];if(s){Object.assign(s,patch);if(s.sel)s.sel=[];if(DN[k])s.n=DN[k]}nav(pg)}

/* ---------- sample orders, so the lists can be tried with a realistic volume ---------- */
function mkSample(st,n){let a=((st.seq+7)*2654435761)>>>0;const R=()=>{a=(a+0x6D2B79F5)>>>0;let t=a;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296},pick=x=>x[Math.floor(R()*x.length)],now=Date.now();
const C1=['Maria Santos','Carlo Mendoza','Bea Villanueva','Rico Dela Cruz','Hannah Lim','Paolo Reyes','Janelle Cruz','Miguel Torres','Aaliyah Ramos','Kenji Aquino','Sofia Navarro','Luis Garcia','Trisha Bautista','Jerome Castillo','Nina Flores','Marco Salazar'],
C2=['Sunrise Sari-Sari Store','Mang Tonyo Sari-Sari','Bright Day Mini Mart','Corner Stop Convenience','Island Breeze Variety','Kuya Lando Store'],
bulk=st.products.filter(p=>p.cat==='Groceries'||p.cat==='Essentials'),shop=st.products.filter(p=>p.cat!=='Groceries'&&p.cat!=='Essentials'||R()<.3),out=[];
for(let k=0;k<n;k++){const age=Math.pow(R(),1.7)*42,ts=now-age*864e5-R()*3e6,trade=R()<.22;let items;
if(trade){const p=pick(bulk),d=pick([10,10,15,20]);items=[{p:p.id,q:10+Math.floor(R()*50),pr:Math.round(p.price*(100-d))/100}];if(R()<.3){const p2=pick(bulk);if(p2.id!==p.id)items.push({p:p2.id,q:6+Math.floor(R()*30),pr:Math.round(p2.price*(100-d))/100})}}
else{items=[];const m=1+Math.floor(R()*3);for(let i=0;i<m;i++){const p=pick(shop);if(items.some(x=>x.p===p.id))continue;items.push({p:p.id,q:p.cat==='Groceries'?1+Math.floor(R()*5):1+Math.floor(R()*(p.price>5000?1:2)),pr:p.price})}}
const r=R();let s;if(age<1)s=r<.6?'Pending':r<.85?'Processing':r<.95?'Ready':'Cancelled';else if(age<3)s=r<.2?'Pending':r<.5?'Processing':r<.8?'Ready':r<.95?'Completed':'Cancelled';else s=r<.88?'Completed':'Cancelled';
const flow=['Pending','Processing','Ready','Completed'],log=[{s:'Pending',ts}];let t2=ts;
if(s==='Cancelled'){t2+=(20+R()*400)*6e4;log.push({s:'Cancelled',ts:Math.min(t2,now)})}else for(let j=1;j<=flow.indexOf(s);j++){t2+=(15+R()*300)*6e4;log.push({s:flow[j],ts:Math.min(t2,now)})}
out.push({type:trade?'trade':'retail',party:trade?pick(C2):pick(C1),items,status:s,ts,log,smp:1})}
out.sort((a,b)=>a.ts-b.ts).forEach(o=>{o.id=nid(o.type==='trade'?'TRD':'ORD')});return out}
function adSample(n){S.orders.push(...mkSample(S,n));S.orders.sort((a,b)=>b.ts-a.ts);save();adRefresh();adNote(`${n} sample orders added.`)}
function adUnsample(){const k=S.orders.filter(o=>o.smp).length;S.orders=S.orders.filter(o=>!o.smp);AS.o.sel=[];AS.t.sel=[];save();adRefresh();adNote(k?`${k} sample orders removed.`:'There were no sample orders.')}
function adReset(){const m=S.me;S=seed();S.me=m;S.orders.push(...mkSample(S,34));S.smpDone=1;S.orders.sort((a,b)=>b.ts-a.ts);AS.cfm='';save();adRefresh();adNote('Demo data reset.')}

/* ---------- document-level events: click a card to open it, keyboard, undo, selection ---------- */
document.addEventListener('click',e=>{const t=e.target;
if(t.closest('[data-close]')){adClose();return}
if(t.closest('[data-undo]')){const f=adU;adU=null;adtoast.classList.remove('on');f&&f();return}
const o=t.closest('[data-open]');if(o&&!t.closest('button,a,input,select,textarea,label,summary')){const i=o.dataset.open.indexOf(':');adOpen(o.dataset.open.slice(0,i),o.dataset.open.slice(i+1),null,!!o.closest('#adw'))}});
document.addEventListener('keydown',e=>{
if((e.key==='Enter'||e.key===' ')&&e.target.matches&&e.target.matches('[data-open]')){e.preventDefault();e.target.click();return}
if(!drw)return;
if(e.key==='Escape'){e.preventDefault();adClose();return}
if(e.key==='Tab'){const f=[...adw.querySelectorAll('button:not([disabled]),input:not([disabled]):not([type=hidden]),select:not([disabled]),summary,[data-open][tabindex="0"]')].filter(x=>x.offsetParent!==null);if(!f.length)return;const i=f.indexOf(document.activeElement);if(e.shiftKey&&i<=0){e.preventDefault();f.at(-1).focus()}else if(!e.shiftKey&&i===f.length-1){e.preventDefault();f[0].focus()}}});
document.addEventListener('change',e=>{const c=e.target.closest&&e.target.closest('[data-sel]');if(c)adSel(c.closest('[data-ws]').dataset.ws,c.dataset.sel,c.checked)});

/* A2 orders + trade: one workspace (w = 'o' customer orders, 't' wholesale) */
const WT=[['active','Needs action'],['Pending','Pending'],['Processing','Processing'],['Ready','Ready'],['Completed','Completed'],['Cancelled','Cancelled'],['all','All']],
tabOk=(k,o)=>k==='all'||(k==='active'?ACT.includes(o.status):o.status===k);
function wsPool(w){const s=AS[w],k=s.q.trim().toLowerCase();return S.orders.filter(o=>(w==='t'?o.type==='trade':s.type==='all'||o.type===s.type)&&inR(o.ts,s.range)&&(!k||(o.id+' '+o.party+' '+o.items.map(i=>pname(i.p)).join(' ')).toLowerCase().includes(k)))}
function wsSort(w,a){const s=AS[w].sort;return a.slice().sort((x,y)=>s==='old'?x.ts-y.ts:s==='hi'?tot(y)-tot(x):s==='lo'?tot(x)-tot(y):s==='az'?x.party.localeCompare(y.party):y.ts-x.ts)}
function wsRows(w){const s=AS[w],p=wsPool(w);return wsSort(w,s.view==='board'?p:p.filter(o=>tabOk(s.tab,o)))}
function wsPage(w){const tr=w==='t';return adph(tr?'Trade and wholesale':'Orders',tr?'Sell in bulk to other businesses at a wholesale price.':'Find an order, check it and move it to the next stage.',tr?`<button class="btn" onclick="adOpen('ntr')">＋ New wholesale order</button>`:'')
+(tr?`<div class="dkpis k3" id="adkpi">${tradeKpi()}</div>`:'')+`<div id="adtabs">${wsTabs(w)}</div><div id="adtool">${wsTool(w)}</div><div id="adres" data-ws="${w}">${wsRes(w)}</div>`}
function wsTabs(w){const s=AS[w];if(s.view==='board')return'';const p=wsPool(w);return `<div class="ad-tabs">${WT.map(([k,l])=>`<button aria-pressed="${s.tab===k}" onclick="adTab('${w}','${k}')">${l}<span class="n">${p.filter(o=>tabOk(k,o)).length}</span></button>`).join('')}</div>`}
function wsTool(w){const s=AS[w],tr=w==='t';return `<div class="ad-bar"><label class="ad-search"><span class="sr">Search</span>${SRCH}<input type="search" placeholder="${tr?'Search order no., business or item':'Search order no., customer or item'}" value="${esc(s.q)}" oninput="adQ('${w}',this.value)" autocomplete="off"></label>
${w==='o'?`<select aria-label="Order type" onchange="adF('o','type',this.value)">${opt([['all','All orders'],['retail','Customer orders'],['trade','Wholesale orders']],x=>x,s.type)}</select>`:''}
<select aria-label="Date" onchange="adF('${w}','range',this.value)">${opt([['all','All time'],['today','Today'],['7','Last 7 days'],['30','Last 30 days']],x=>x,s.range)}</select>
<select aria-label="Sort" onchange="adF('${w}','sort',this.value)">${opt([['new','Newest first'],['old','Oldest first'],['hi','Highest total'],['lo','Lowest total'],['az',tr?'Business A–Z':'Customer A–Z']],x=>x,s.sort)}</select>
<div class="ad-seg" role="group" aria-label="View"><button aria-pressed="${s.view==='list'}" onclick="adF('${w}','view','list')">List</button><button aria-pressed="${s.view==='board'}" onclick="adF('${w}','view','board')">Board</button></div></div>`}
function ordRow(o,w){const on=AS[w].sel.includes(o.id),nx=NX[o.status],n=o.items.length;return `<div class="ad-row ord${on?' sel':''}" data-open="order:${o.id}" tabindex="0" role="button" aria-label="Open ${o.id}, ${esc(o.party)}, ${o.status}"><label class="ad-chk" title="Select"><input type="checkbox" data-sel="${o.id}" ${on?'checked':''} aria-label="Select ${o.id}"></label><div class="ad-id"><b>${o.id}</b><small>${ago(o.ts)}</small></div><div class="ad-who"><b>${esc(o.party)}</b><small>${o.type==='trade'?'Wholesale · ':''}${pl(n,'item')} · ${pl(units(o),'unit')}</small></div><div class="ad-th">${thm(o)}</div><b class="ad-amt">${peso(tot(o))}</b>${pill(o.status)}<div class="ad-act">${nx?`<button class="btn sm" onclick="adNext('${o.id}')">${nx}</button>`:''}</div></div>`}
const bCard=o=>`<div class="ad-bc" data-open="order:${o.id}" tabindex="0" role="button" aria-label="Open ${o.id}"><div class="row"><b>${o.id}</b><small>${ago(o.ts)}</small></div><span>${esc(o.party)}</span><b>${peso(tot(o))}</b>${NXT[o.status]?`<button class="btn sm wide" onclick="adNext('${o.id}')">→ ${NXT[o.status]}</button>`:''}</div>`;
function wsRes(w){const s=AS[w],tr=w==='t',rows=wsRows(w),filt=!!s.q.trim()||s.range!=='all'||(w==='o'&&s.type!=='all'),what=tr?'wholesale orders':'orders',clr=filt?`<button class="lnk" onclick="adClr('${w}')">Clear filters</button>`:'';
if(!rows.length)return `<div class="card ad-empty"><span class="ic big">${ICO('🛍')}</span><b>${filt?'No orders match your search':'No orders in this view'}</b><span>${filt?'Try another word, or clear the filters.':'New orders will show up here.'}</span>${filt?`<button class="btn sm" onclick="adClr('${w}')">Clear filters</button>`:''}</div>`;
if(s.view==='board'){return `<div class="ad-sum"><span>${rows.length} ${what} · the latest 6 of each stage are shown</span>${clr}</div><div class="ad-board">${ST.map(st=>{const c=rows.filter(o=>o.status===st);return `<div class="ad-col"><div class="ad-ch"><b class="${SC[st]==='mute'?'':SC[st]}">${st}</b><span class="pill">${c.length}</span></div>${c.slice(0,6).map(bCard).join('')||'<div class="ad-none">Nothing here</div>'}${c.length>6?`<button class="ad-more-btn" onclick="adTabView('${w}','${st}')">View all ${c.length} →</button>`:''}</div>`}).join('')}</div>`}
const show=rows.slice(0,s.n),all=show.every(o=>s.sel.includes(o.id));let last='';
const L=show.map(o=>{let g='';if(s.sort==='new'||s.sort==='old'){const d=dayLbl(o.ts);if(d!==last){last=d;g=`<div class="ad-gh">${d}<span>${show.filter(x=>dayLbl(x.ts)===d).length}</span></div>`}}return g+ordRow(o,w)}).join('');
return `<div class="ad-sum"><label><input type="checkbox" data-selall ${all?'checked':''} onchange="adSelAll('${w}',this.checked)">Select all shown</label><span>Showing ${show.length} of ${rows.length} ${what}</span>${clr}</div><div class="ad-list">${L}${rows.length>show.length?`<button class="ad-more-btn" onclick="adMore('${w}')">Show ${Math.min(15,rows.length-show.length)} more</button>`:''}</div>`}
function wsRefresh(w){set_('adtabs',wsTabs(w));set_('adtool',wsTool(w));set_('adres',wsRes(w));adBulk()}
function adTab(w,k){const s=AS[w];s.tab=k;s.n=DN[w];s.sel=[];if(s.view==='board')s.view='list';wsRefresh(w)}
function adQ(w,v){const s=AS[w];s.q=v;s.n=DN[w];s.sel=[];set_('adtabs',wsTabs(w));set_('adres',wsRes(w));adBulk()}
function adF(w,k,v){const s=AS[w];s[k]=v;s.n=DN[w];s.sel=[];set_('adtabs',wsTabs(w));set_('adres',wsRes(w));if(k==='view')set_('adtool',wsTool(w));adBulk()}
function adClr(w){const s=AS[w];s.q='';s.range='all';if(w==='o')s.type='all';s.n=DN[w];s.sel=[];wsRefresh(w)}
function adMore(w){AS[w].n+=15;set_('adres',wsRes(w))}
function adTabView(w,st){const s=AS[w];s.tab=st;s.view='list';s.n=DN[w];s.sel=[];wsRefresh(w)}
function adSel(w,id,on){const s=AS[w];s.sel=on?[...new Set([...s.sel,id])]:s.sel.filter(x=>x!==id);const c=document.querySelector(`[data-sel="${id}"]`),r=c&&c.closest('.ad-row');r&&r.classList.toggle('sel',on);
const a=document.querySelector('[data-selall]');if(a){const sh=wsRows(w).slice(0,s.n);a.checked=sh.length>0&&sh.every(o=>s.sel.includes(o.id))}adBulk()}
function adSelAll(w,on){const s=AS[w];s.sel=on?wsRows(w).slice(0,s.n).map(o=>o.id):[];AS.cfm='';set_('adres',wsRes(w));adBulk()}
function adSelClr(w){AS[w].sel=[];AS.cfm='';set_('adres',wsRes(w));adBulk()}
const adbulk=document.createElement('div');adbulk.id='ad-bulk';adbulk.className='ad-bulk';adbulk.hidden=true;adbulk.setAttribute('role','region');adbulk.setAttribute('aria-label','Selected orders');document.body.appendChild(adbulk);
function adBulk(){const w=WV[view],s=w&&AS[w],n=s?s.sel.length:0;document.body.classList.toggle('bulk',n>0);if(!n){adbulk.hidden=true;adbulk.innerHTML='';return}
const os=s.sel.map(id=>S.orders.find(o=>o.id===id)).filter(Boolean),mv=os.filter(o=>NXT[o.status]),same=mv.length&&mv.every(o=>o.status===mv[0].status),cn=os.filter(o=>ACT.includes(o.status));
adbulk.hidden=false;adbulk.innerHTML=`<b>${n} selected</b>${mv.length?`<button class="btn sm" onclick="adBulkNext('${w}')">${same?NX[mv[0].status]:'Move to next step'} (${mv.length})</button>`:''}${cn.length?(AS.cfm==='bulk'?`<span>Cancel ${cn.length}?</span><button class="btn sm danger" onclick="adBulkCancel('${w}')">Yes, cancel</button><button class="btn sm ghost" onclick="AS.cfm='';adBulk()">Keep</button>`:`<button class="btn sm ghost" onclick="AS.cfm='bulk';adBulk()">Cancel orders</button>`):''}<button class="x" onclick="adSelClr('${w}')">Clear</button>`}
const selOrders=w=>AS[w].sel.map(id=>S.orders.find(o=>o.id===id)).filter(Boolean);
function adBulkNext(w){adMove(selOrders(w).filter(o=>NXT[o.status]).map(o=>[o.id,NXT[o.status]]))}
function adBulkCancel(w){adMove(selOrders(w).filter(o=>ACT.includes(o.status)).map(o=>[o.id,'Cancelled']))}

/* order detail panel */
DR.order=id=>{const o=S.orders.find(x=>x.id===id);if(!o)return null;const tr=o.type==='trade',nx=NX[o.status],can=ACT.includes(o.status),ask=AS.cfm==='o:'+id,log=o.log||[{s:'Pending',ts:o.ts}],open=ACT.includes(o.status);
const body=`<div class="row"><div class="ad-who2">${av(o.party)}<div><b>${esc(o.party)}</b><small>${tr?'Wholesale customer':'Customer'} · ${tm2(o.ts)}</small></div></div>${pill(o.status)}</div>
${o.status==='Cancelled'?`<p class="note">This order was cancelled.${o.smp?'':' Its items went back into stock.'}</p>`:`<div class="steps">${FL.map((s,i)=>`<div class="${i<=FL.indexOf(o.status)?'on':''}"><i></i>${s}</div>`).join('')}</div>`}
<div class="ad-sec">Items</div><div class="ad-lines">${o.items.map(i=>{const p=prod(i.p);return `<div class="ad-li"${p?` data-open="prod:${p.id}" tabindex="0" role="button" aria-label="Open ${esc(p.name)}"`:' style="cursor:default"'}><span class="tile mini">${p?pic(p):'📦'}</span><div class="grow"><b>${esc(pname(i.p))}</b><small>${i.q} × ${peso(i.pr)}${tr&&p&&p.price>i.pr?` <s>${peso(p.price)}</s>`:''}${p&&open?` · ${p.stock} in stock`:''}</small></div><b>${peso(i.q*i.pr)}</b></div>`}).join('')}</div>
<div class="ad-tot"><span>${pl(units(o),'unit')}</span><span>Total</span><b>${peso(tot(o))}</b></div>
<div class="ad-sec">History</div><ol class="ad-log">${log.slice().reverse().map(x=>`<li>${x.u?`Moved back to ${x.s}`:LBL[x.s]||x.s}<small>${tm2(x.ts)}</small></li>`).join('')}</ol>`;
const foot=`${nx?`<button class="btn grow" onclick="adNext('${id}')">${nx}</button>`:''}${can?(ask?`<span class="ad-cf">Cancel this order?${o.smp?'':' The items go back into stock.'}</span><button class="btn danger" onclick="adCancel('${id}')">Yes, cancel it</button><button class="btn ghost" onclick="AS.cfm='';adDraw()">Keep order</button>`:`<button class="btn ghost" onclick="AS.cfm='o:${id}';adDraw()">Cancel order</button>`):''}${ask?'':'<button class="btn ghost" onclick="adPrint()">Print slip</button>'}`;
return{k:tr?'Wholesale order':'Customer order',title:o.id,body,foot}};
function adPrint(){document.body.classList.add('adp');const f=()=>{document.body.classList.remove('adp');removeEventListener('afterprint',f)};addEventListener('afterprint',f);try{print()}catch(e){f()}}

/* trade: KPI cards + new wholesale order form */
function tradeKpi(){const t=S.orders.filter(o=>o.type==='trade'&&o.status!=='Cancelled'),act=t.filter(o=>ACT.includes(o.status)),k=(c,i,l,v,sb,f)=>`<button class="card dk${c}" onclick="${f}" data-tip="${sb}"><span class="ic">${ICO(i)}</span><div><small>${l}</small><b>${v}</b><em>${sb}</em></div><i class="go" aria-hidden="true">→</i></button>`;
return k(act.length?' hot':'','🏪','To process',act.length,act.length?'Show the ones to finish':'All caught up',`adTab('t','active')`)+k('','📦','Wholesale orders',t.length,'Show all of them',`adTab('t','all')`)+k('','💰','Wholesale sales',peso(t.reduce((a,o)=>a+tot(o),0)),'Open records',`adJump('records',{tab:'trade'})`)}
DR.ntr=(id,ex)=>{const prods=S.products.filter(p=>p.stock>0),biz=[...new Set(S.orders.filter(o=>o.type==='trade').map(o=>o.party))];
return{k:'Wholesale',title:'New wholesale order',body:`<form class="ad-fg" id="adtf" onsubmit="event.preventDefault();adSub('tr',Object.fromEntries(new FormData(this)))"><label class="ad-f">Business name<input name="b" required list="adbiz" placeholder="e.g. Sunrise Sari-Sari Store" autocomplete="off"></label><datalist id="adbiz">${biz.map(b=>`<option value="${esc(b)}">`).join('')}</datalist>
${sel('p','Product',opt(prods,p=>[p.id,`${p.name} (${p.stock} in stock)`],ex.p||''),'onchange="adTrSum()"')}
<div class="ad-2">${fld('q','Quantity','number','min="1" value="10" oninput="adTrSum()"')}${fld('d','Wholesale discount (%)','number','min="0" max="90" step="any" value="10" oninput="adTrSum()"')}</div>
<div class="ad-sumrow" id="adtsum"></div><p class="ad-hint" id="adthint"></p><button class="btn wide">Record wholesale order</button></form>`}};
function adTrSum(){const f=document.getElementById('adtf');if(!f)return;const p=prod(f.p.value),q=+f.q.value||0,d=Math.min(90,Math.max(0,+f.d.value||0));if(!p)return;const u=Math.round(p.price*(100-d))/100;
set_('adtsum',`<span>${q} × ${peso(u)} <s>${peso(p.price)}</s></span><b>${peso(u*q)}</b>`);const h=document.getElementById('adthint');if(h){h.className='ad-hint'+(q>p.stock?' bad':'');h.textContent=q>p.stock?`Only ${p.stock} in stock. Lower the quantity.`:`${p.stock} in stock now, ${p.stock-q} left after this order.`}}

/* dashboard: the page is your own Dashboard design. Its cards now open the filtered pages and panels; the demo-data strip sits underneath */
const adGo=(pg,tab)=>{const p=tab?{tab,q:''}:{};if(pg==='orders'&&tab)Object.assign(p,{range:'all',type:'all',sort:tab==='active'||ACT.includes(tab)?'old':'new'});if(pg==='records'&&tab)p.range='all';adJump(pg,p)};
function demoStrip(){const smp=S.orders.filter(o=>o.smp).length;return `<div class="ad-demo" id="addemo"><div class="grow"><b>Demo data</b> · ${smp?pl(smp,'sample order')+' mixed in, so you can try search, filters and bulk actions.':'No sample orders right now.'}</div><button class="btn ghost sm" onclick="adSample(30)">Add 30 sample orders</button>${smp?'<button class="btn ghost sm" onclick="adUnsample()">Remove sample orders</button>':''}${AS.cfm==='reset'?`<span>Reset everything?</span><button class="btn danger sm" onclick="adReset()">Yes, reset</button><button class="btn ghost sm" onclick="adDemoCfm('')">No</button>`:`<button class="btn ghost sm" onclick="adDemoCfm('reset')">Reset demo data</button>`}</div>`}
function adDemoCfm(v){AS.cfm=v;const e=document.getElementById('addemo');if(e)e.outerHTML=demoStrip()}
V.dashboard=()=>DASH()+demoStrip();

/* A4 inventory, purchasing, suppliers */
const invTab=(k,p)=>k==='all'||(k==='in'?p.stock>p.min:k==='low'?p.stock>0&&p.stock<=p.min:p.stock===0),
stkc=p=>{const[t,c]=stk(p);return{t,c,pct:Math.min(100,Math.round(p.stock/((p.min||1)*3)*100))}},
stkBar=p=>{const{c,pct}=stkc(p);return `<div class="ad-stk"><div class="row"><b class="ad-n">${p.stock}</b><small>reorder at ${p.min}</small></div><div class="bar ${c}"><i style="width:${pct}%"></i></div></div>`};
function invPool(){const s=AS.inv,k=s.q.trim().toLowerCase();return S.products.filter(p=>(s.cat==='All'||p.cat===s.cat)&&(!k||(p.name+' '+p.cat).toLowerCase().includes(k)))}
function invRows(){const s=AS.inv,o=s.sort;return invPool().filter(p=>invTab(s.tab,p)).sort((a,b)=>o==='lo'?a.stock-b.stock:o==='hi'?b.stock-a.stock:o==='pl'?a.price-b.price:o==='ph'?b.price-a.price:o==='cat'?CF.indexOf(a.cat)-CF.indexOf(b.cat)||a.name.localeCompare(b.name):a.name.localeCompare(b.name))}
function prRow(p){const{t,c}=stkc(p),inc=incoming(p.id);return `<div class="ad-row prd" data-open="prod:${p.id}" tabindex="0" role="button" aria-label="Open ${esc(p.name)}, ${p.stock} in stock"><span class="tile mini ad-th1">${pic(p)}</span><div class="ad-who"><b>${esc(p.name)}</b><small>${esc(p.cat)}</small></div><div class="ad-amt2">${price(p)}</div>${stkBar(p)}<span class="pill ${c}">${t}</span><div class="ad-act">${p.stock<=p.min?(inc?`<span class="pill info">+${inc} on the way</span>`:`<button class="btn sm" onclick="adOpen('npo','',{p:'${p.id}'})">Reorder</button>`):''}</div></div>`}
function prCard(p){const{t,c,pct}=stkc(p),inc=incoming(p.id);return `<div class="card ic2 ad-click" data-open="prod:${p.id}" tabindex="0" role="button" aria-label="Open ${esc(p.name)}, ${p.stock} in stock"><div class="tile">${pic(p)}</div><b>${esc(p.name)}</b><small>${esc(p.cat)} · ${peso(p.price)}</small><div class="row"><span class="big2">${p.stock}</span><span class="pill ${c}">${t}</span></div><div class="bar ${c}"><i style="width:${pct}%"></i></div><small>Reorder at ${p.min}</small><div class="adjb">${[-10,-1,1,10].map(n=>`<button aria-label="Change ${esc(p.name)} stock by ${n}" onclick="adStock('${p.id}',${n})">${n>0?'+':'−'}${Math.abs(n)}</button>`).join('')}</div>${p.stock<=p.min?(inc?`<span class="pill info ad-way">+${inc} on the way</span>`:`<button class="btn sm" onclick="adOpen('npo','',{p:'${p.id}'})">Reorder</button>`):''}</div>`}
function invPage(){return adph('Inventory','Check stock, correct a count, or restock before items run out.',`<button class="btn" onclick="adOpen('nprod')">＋ Add product</button>`)+`<div id="adtabs">${invTabs()}</div><div id="adtool">${invTool()}</div><div id="adres">${invRes()}</div>`}
function invTabs(){const s=AS.inv,p=invPool();return `<div class="ad-tabs">${[['all','All'],['in','In stock'],['low','Low stock'],['out','Out of stock']].map(([k,l])=>`<button aria-pressed="${s.tab===k}" onclick="adI('tab','${k}')">${l}<span class="n">${p.filter(x=>invTab(k,x)).length}</span></button>`).join('')}</div>`}
function invTool(){const s=AS.inv;return `<div class="ad-bar"><label class="ad-search"><span class="sr">Search</span>${SRCH}<input type="search" placeholder="Search products" value="${esc(s.q)}" oninput="adIQ(this.value)" autocomplete="off"></label>
<select aria-label="Category" onchange="adI('cat',this.value)">${opt(CF,x=>[x,x==='All'?'All categories':x],s.cat)}</select>
<select aria-label="Sort" onchange="adI('sort',this.value)">${opt([['name','Name A–Z'],['lo','Stock: low to high'],['hi','Stock: high to low'],['pl','Price: low to high'],['ph','Price: high to low'],['cat','Category']],x=>x,s.sort)}</select>
<div class="ad-seg" role="group" aria-label="View"><button aria-pressed="${s.view==='cards'}" onclick="adI('view','cards')">Cards</button><button aria-pressed="${s.view==='list'}" onclick="adI('view','list')">List</button></div></div>`}
function invRes(){const s=AS.inv,r=invRows(),show=r.slice(0,s.n),filt=!!s.q.trim()||s.cat!=='All'||s.tab!=='all';
if(!r.length)return `<div class="card ad-empty"><span class="ic big">${ICO('📦')}</span><b>No products match</b><span>Try another word or category.</span>${filt?'<button class="btn sm" onclick="adIClr()">Clear filters</button>':''}</div>`;
return `<div class="ad-sum"><span>Showing ${show.length} of ${r.length} products</span>${filt?'<button class="lnk" onclick="adIClr()">Clear filters</button>':''}</div>${s.view==='cards'?`<div class="grid ad-pgrid">${show.map(prCard).join('')}</div>`:`<div class="ad-list">${show.map(prRow).join('')}</div>`}${r.length>show.length?`<div class="ad-list"><button class="ad-more-btn" onclick="AS.inv.n+=30;set_('adres',invRes())">Show ${Math.min(30,r.length-show.length)} more</button></div>`:''}`}
function invRefresh(){set_('adtabs',invTabs());set_('adres',invRes())}
function adI(k,v){const s=AS.inv;s[k]=v;s.n=30;invRefresh();if(k==='view')set_('adtool',invTool())}
function adIQ(v){AS.inv.q=v;AS.inv.n=30;invRefresh()}
function adIClr(){Object.assign(AS.inv,{q:'',cat:'All',tab:'all',n:30});set_('adtool',invTool());invRefresh()}
function adStock(id,n){const p=prod(id);if(!p)return;const was=p.stock;p.stock=Math.max(0,p.stock+n);save();adNote(`${p.name}: ${p.stock} in stock.`,()=>{p.stock=was;save();adRefresh()});adRefresh()}
function adSetStock(id,v){const p=prod(id),n=Math.floor(+v);if(!p||!(n>=0)||v==='')return adNote('Enter a count of 0 or more.');p.stock=n;save();adNote(`${p.name}: ${p.stock} in stock.`);adRefresh()}

/* purchase order form, shared by the "New purchase order" panel and the product panel */
function poForm(ex){ex=ex||{};const pid=ex.p||'',pr=prod(pid),l=pid?lastPO(pid):null,sid=ex.s||(l&&l.s)||(S.suppliers[0]||{}).id,low=S.products.filter(p=>p.stock<=p.min),rest=S.products.filter(p=>p.stock>p.min),
q0=ex.q||(pr?sugg(pr):''),c0=ex.cost||(l?l.cost:'');
if(!S.suppliers.length)return `<p class="note">Add a supplier first, then you can order stock from them.</p><button class="btn" onclick="adOpen('nsup')">Add a supplier</button>`;
return `<form class="ad-fg" id="adpf" onsubmit="event.preventDefault();adSub('po',Object.fromEntries(new FormData(this)))">${sel('s','Supplier',opt(S.suppliers,s=>[s.id,s.name],sid))}
${ex.lock?`<input type="hidden" name="p" value="${pid}">`:sel('p','Product',(low.length?`<optgroup label="Needs restocking">${opt(low,p=>[p.id,`${p.name} (${p.stock} left)`],pid)}</optgroup>`:'')+`<optgroup label="All other products">${opt(rest,p=>[p.id,p.name],pid)}</optgroup>`,'onchange="adPoPick(this.value)"')}
<div class="ad-2">${fld('q','Quantity','number',`min="1" value="${q0}" oninput="adPoSum()"`)}${fld('cost','Unit cost (₱)','number',`min="0" step="any" value="${c0}" oninput="adPoSum()"`)}</div>
<div class="ad-sumrow" id="adpsum"></div><button class="btn wide">Record purchase order</button></form>`}
function adPoPick(pid){const f=adw.querySelector('#adpf');if(!f)return;const p=prod(pid),l=lastPO(pid);if(l){f.s.value=l.s;f.cost.value=l.cost}if(p)f.q.value=sugg(p);adPoSum()}
function adPoSum(){const f=adw.querySelector('#adpf');if(!f)return;const p=prod(f.p.value),q=+f.q.value||0,c=+f.cost.value||0;set_('adpsum',p?`<span>${q} × ${peso(c)} · stock ${p.stock} → ${p.stock+q}</span><b>${peso(q*c)}</b>`:'')}
DR.npo=(id,ex)=>({k:'Purchasing',title:'New purchase order',body:poForm(ex)});
DR.nprod=()=>({k:'Inventory',title:'Add a product',body:`<form class="ad-fg" onsubmit="event.preventDefault();adSub('prod',Object.fromEntries(new FormData(this)))">${fld('name','Product name','text','placeholder="e.g. Black Oversized Tee"')}${sel('cat','Category',opt(CAT,x=>[x[0],x[0]]))}<div class="ad-2">${fld('price','Price (₱)','number','min="0" step="any"')}${fld('stock','Opening stock','number','min="0" value="0"')}</div>${fld('min','Reorder level','number','min="0" value="5"')}<p class="ad-hint">You will be reminded to restock when the count reaches the reorder level.</p><button class="btn wide">Add product</button></form>`});

/* product panel */
DR.prod=id=>{const p=prod(id);if(!p)return null;const{t,c}=stkc(p),inc=S.purchases.filter(x=>x.p===id&&x.status==='Ordered'),ords=S.orders.filter(o=>o.items.some(i=>i.p===id)).sort((a,b)=>b.ts-a.ts).slice(0,5),need=p.stock<=p.min&&!inc.length;
const body=`<div class="tile ad-pimg">${pic(p)}</div><div class="row"><div><b>${price(p)}</b><small>${esc(p.cat)} · Item code ${esc(p.id).toUpperCase()}</small></div><span class="pill ${c}">${t}</span></div>
<div class="ad-sec">Stock</div><div class="ad-bigstock"><b>${p.stock}</b><span class="mute">in stock · reorder at ${p.min}</span></div><div class="bar ${c}"><i style="width:${stkc(p).pct}%"></i></div>
<div class="adjb">${[-10,-1,1,10].map(n=>`<button aria-label="Change stock by ${n}" onclick="adStock('${id}',${n})">${n>0?'+':'−'}${Math.abs(n)}</button>`).join('')}</div>
<form class="ad-inline" onsubmit="event.preventDefault();adSetStock('${id}',this.n.value)"><input name="n" type="number" min="0" placeholder="Or type the exact count"><button class="btn sm ghost">Set count</button></form>
${inc.length?`<div class="ad-sec">On the way</div><div class="ad-lines">${inc.map(x=>`<div class="ad-li" data-open="po:${x.id}" tabindex="0" role="button"><div class="grow"><b>+${pl(x.q,'unit')}</b><small>${x.id} · ${esc(sname(x.s)||'')}</small></div><button class="btn sm" onclick="adRecv('${x.id}')">Mark received</button></div>`).join('')}</div>`:''}
<details class="ad-det" ${need?'open':''}><summary>Restock this item</summary>${poForm({p:id,lock:1})}</details>
<details class="ad-det"><summary>Edit details</summary><form class="ad-fg" onsubmit="event.preventDefault();adSub('prodEdit',Object.fromEntries(new FormData(this)),'${id}')">${fld('name','Product name','text',`value="${esc(p.name)}"`)}${sel('cat','Category',opt(CAT,x=>[x[0],x[0]],p.cat))}<div class="ad-2">${fld('price','Price (₱)','number',`min="0" step="any" value="${p.price}"`)}<label class="ad-f">Regular price (optional, shows a deal)<input name="was" type="number" min="0" step="any" value="${p.was||''}"></label></div>${fld('min','Reorder level','number',`min="0" value="${p.min}"`)}<button class="btn wide">Save changes</button></form></details>
${ords.length?`<div class="ad-sec">Recent orders with this item</div><div class="ad-lines">${ords.map(o=>`<div class="ad-li" data-open="order:${o.id}" tabindex="0" role="button"><div class="grow"><b>${o.id} · ${esc(o.party)}</b><small>${pl(o.items.find(i=>i.p===id).q,'unit')} · ${ago(o.ts)}</small></div>${pill(o.status)}</div>`).join('')}</div>`:''}`;
return{k:'Product',title:esc(p.name),body}};

/* purchasing */
const poTab=(k,p)=>k==='all'||(k==='open'?p.status==='Ordered':k==='received'?p.status==='Received':p.status==='Cancelled');
function poPool(){const k=AS.po.q.trim().toLowerCase();return S.purchases.filter(p=>!k||(p.id+' '+pname(p.p)+' '+(sname(p.s)||'')).toLowerCase().includes(k))}
function lowPool(){const k=AS.po.q.trim().toLowerCase();return S.products.filter(p=>p.stock<=p.min&&(!k||(p.name+' '+p.cat).toLowerCase().includes(k))).sort((a,b)=>a.stock/(a.min||1)-b.stock/(b.min||1))}
function poRow(p){const pr=prod(p.p);return `<div class="ad-row po" data-open="po:${p.id}" tabindex="0" role="button" aria-label="Open ${p.id}"><span class="tile mini ad-th1">${pr?pic(pr):'📦'}</span><div class="ad-who"><b>${esc(pname(p.p))}</b><small>${p.id} · ${fmt(p.ts)}</small></div><div class="ad-sup">${esc(sname(p.s)||'—')}</div><div class="ad-qc">${p.q} × ${peso(p.cost)}</div><b class="ad-amt">${peso(p.q*p.cost)}</b>${pill(p.status)}<div class="ad-act">${p.status==='Ordered'?`<button class="btn sm" onclick="adRecv('${p.id}')">Mark received</button>`:''}</div></div>`}
function poPage(){return adph('Purchasing','Order stock from suppliers and receive it when it arrives.',`<button class="btn" onclick="adOpen('npo')">＋ New purchase order</button>`)+`<div id="adtabs">${poTabs()}</div><div id="adtool"><div class="ad-bar"><label class="ad-search"><span class="sr">Search</span>${SRCH}<input type="search" placeholder="Search product, supplier or order no." value="${esc(AS.po.q)}" oninput="adPQ(this.value)" autocomplete="off"></label></div></div><div id="adres">${poRes()}</div>`}
function poTabs(){const s=AS.po,p=poPool();return `<div class="ad-tabs">${[['restock','Needs restocking',lowPool().length],['open','On order',p.filter(x=>poTab('open',x)).length],['received','Received',p.filter(x=>poTab('received',x)).length],['cancelled','Cancelled',p.filter(x=>poTab('cancelled',x)).length],['all','All orders',p.length]].map(([k,l,n])=>`<button aria-pressed="${s.tab===k}" onclick="adPT('${k}')">${l}<span class="n">${n}</span></button>`).join('')}</div>`}
function poRes(){const s=AS.po;if(s.tab==='restock'){const r=lowPool();return r.length?`<div class="ad-sum"><span>${pl(r.length,'item')} at or below the reorder level. Press Reorder to start a purchase order.</span></div><div class="ad-list">${r.map(prRow).join('')}</div>`:`<div class="card ad-empty"><span class="ic big">${ICO('📦')}</span><b>Nothing to restock</b><span>Every item is above its reorder level.</span></div>`}
const r=poPool().filter(p=>poTab(s.tab,p)).sort((a,b)=>b.ts-a.ts),show=r.slice(0,s.n);
return r.length?`<div class="ad-sum"><span>Showing ${show.length} of ${pl(r.length,'purchase order')}</span></div><div class="ad-list">${show.map(poRow).join('')}${r.length>show.length?`<button class="ad-more-btn" onclick="AS.po.n+=20;set_('adres',poRes())">Show more</button>`:''}</div>`:`<div class="card ad-empty"><span class="ic big">${ICO('🚚')}</span><b>No purchase orders here</b><span>${s.q.trim()?'Try another word.':'Orders you place with suppliers will show up here.'}</span><button class="btn sm" onclick="adOpen('npo')">New purchase order</button></div>`}
function poRefresh(){set_('adtabs',poTabs());set_('adres',poRes())}
function adPT(k){AS.po.tab=k;AS.po.n=20;poRefresh()}
function adPQ(v){AS.po.q=v;AS.po.n=20;poRefresh()}
function adRecv(id){const o=S.purchases.find(p=>p.id===id);if(!o||o.status!=='Ordered')return;const pr=prod(o.p);o.status='Received';o.rts=Date.now();if(pr)pr.stock+=o.q;save();
adNote(`${id} received. ${pr?pr.name+' is now '+pr.stock+' in stock.':''}`,()=>{o.status='Ordered';delete o.rts;if(pr)pr.stock=Math.max(0,pr.stock-o.q);save();adRefresh();adNote('Receipt undone.')});adRefresh()}
function adCancelPO(id){const o=S.purchases.find(p=>p.id===id);if(!o||o.status!=='Ordered')return;o.status='Cancelled';AS.cfm='';save();adNote(`${id} cancelled.`,()=>{o.status='Ordered';save();adRefresh();adNote('Change undone.')});adRefresh()}
DR.po=id=>{const p=S.purchases.find(x=>x.id===id);if(!p)return null;const pr=prod(p.p),sp=S.suppliers.find(s=>s.id===p.s),ask=AS.cfm==='po:'+id;
const body=`<div class="row"><span class="mute">Placed ${tm2(p.ts)}</span>${pill(p.status)}</div>${p.status==='Cancelled'?'<p class="note">This purchase order was cancelled. Stock was not changed.</p>':`<div class="steps"><div class="on"><i></i>Ordered</div><div class="${p.status==='Received'?'on':''}"><i></i>Received${p.rts?' · '+fmt(p.rts):''}</div></div>`}
<div class="ad-sec">Product</div><div class="ad-lines"><div class="ad-li"${pr?` data-open="prod:${pr.id}" tabindex="0" role="button"`:' style="cursor:default"'}><span class="tile mini">${pr?pic(pr):'📦'}</span><div class="grow"><b>${esc(pname(p.p))}</b><small>${pr?pr.stock+' in stock now':'Product removed'}</small></div></div>${sp?`<div class="ad-li" data-open="sup:${sp.id}" tabindex="0" role="button">${av(sp.name)}<div class="grow"><b>${esc(sp.name)}</b><small>${esc(sp.contact)} · ${esc(sp.phone)}</small></div></div>`:''}</div>
<div class="ad-kv"><div><small>Quantity</small><b>${p.q}</b></div><div><small>Unit cost</small><b>${peso(p.cost)}</b></div><div><small>Total</small><b>${peso(p.q*p.cost)}</b></div></div>`;
const foot=p.status==='Ordered'?`<button class="btn grow" onclick="adRecv('${id}')">Mark received</button>${ask?`<span class="ad-cf">Cancel this purchase order?</span><button class="btn danger" onclick="adCancelPO('${id}')">Yes, cancel it</button><button class="btn ghost" onclick="AS.cfm='';adDraw()">Keep it</button>`:`<button class="btn ghost" onclick="AS.cfm='po:${id}';adDraw()">Cancel order</button>`}`:'';
return{k:'Purchase order',title:p.id,body,foot}};

/* suppliers */
function supPage(){return adph('Suppliers','The businesses you buy stock from, what you bought and who to call.',`<button class="btn" onclick="adOpen('nsup')">＋ Add supplier</button>`)+supSlider()+`<div class="ad-bar"><label class="ad-search"><span class="sr">Search</span>${SRCH}<input type="search" placeholder="Search suppliers" value="${esc(AS.sup.q)}" oninput="AS.sup.q=this.value;set_('adres',supRes())" autocomplete="off"></label></div><div id="adres">${supRes()}</div>`}
function supRes(){const k=AS.sup.q.trim().toLowerCase(),r=S.suppliers.filter(s=>!k||(s.name+' '+s.contact+' '+s.phone).toLowerCase().includes(k));
return r.length?`<div class="cardgrid">${r.map(s=>{const l=S.purchases.filter(p=>p.s===s.id&&p.status!=='Cancelled'),o=l.filter(p=>p.status==='Ordered').length;return `<div class="card ad-click" data-open="sup:${s.id}" tabindex="0" role="button" aria-label="Open ${esc(s.name)}">${supTh(s)}<div class="row">${av(s.name)}<div class="grow"><b>${esc(s.name)}</b><small>${esc([s.contact,s.phone].filter(Boolean).join(' · ')||'No contact added yet')}</small></div>${o?`<span class="pill info">${o} on order</span>`:''}</div><div class="kv"><div><small>Purchases</small><b>${l.length}</b></div><div><small>Total spent</small><b>${peso(l.reduce((a,p)=>a+p.q*p.cost,0))}</b></div></div><button class="btn sm" onclick="adOpen('npo','',{s:'${s.id}'})">New purchase order</button></div>`}).join('')}</div>`:`<div class="card ad-empty"><span class="ic big">${ICO('🚚')}</span><b>No suppliers found</b><span>${k?'Try another word.':'Add the businesses you buy stock from.'}</span><button class="btn sm" onclick="adOpen('nsup')">Add supplier</button></div>`}
DR.nsup=()=>({k:'Suppliers',title:'Add a supplier',body:`<form class="ad-fg" onsubmit="event.preventDefault();adSub('sup',Object.fromEntries(new FormData(this)))">${fld('name','Supplier name','text')}${fld('contact','Contact person','text')}${fld('phone','Phone','tel')}<button class="btn wide">Add supplier</button></form>`});
DR.sup=id=>{const s=S.suppliers.find(x=>x.id===id);if(!s)return null;const l=S.purchases.filter(p=>p.s===id).sort((a,b)=>b.ts-a.ts),ok=l.filter(p=>p.status!=='Cancelled');
const body=`${supTh(s)}<div class="ad-who2">${av(s.name)}<div><b>${esc(s.contact||'No contact person yet')}</b><small>${s.phone?`<a href="tel:${esc(s.phone.replace(/\s/g,''))}" style="color:inherit">${esc(s.phone)}</a>`:'No phone yet. Add it under Edit contact details.'}</small></div></div>
<div class="ad-kv"><div><small>Purchases</small><b>${ok.length}</b></div><div><small>On order</small><b>${l.filter(p=>p.status==='Ordered').length}</b></div><div><small>Total spent</small><b>${peso(ok.reduce((a,p)=>a+p.q*p.cost,0))}</b></div></div>
<button class="btn" onclick="adOpen('npo','',{s:'${id}'},true)">New purchase order</button>
<div class="ad-sec">Purchase history</div>${l.length?`<div class="ad-lines">${l.map(p=>{const pr=prod(p.p);return `<div class="ad-li" data-open="po:${p.id}" tabindex="0" role="button"><span class="tile mini">${pr?pic(pr):'📦'}</span><div class="grow"><b>${p.q} × ${esc(pname(p.p))}</b><small>${p.id} · ${fmt(p.ts)} · ${peso(p.q*p.cost)}</small></div>${pill(p.status)}</div>`}).join('')}</div>`:'<p class="mute">No purchases from this supplier yet.</p>'}
<details class="ad-det"><summary>Edit contact details</summary><form class="ad-fg" onsubmit="event.preventDefault();adSub('supEdit',Object.fromEntries(new FormData(this)),'${id}')">${fld('name','Supplier name','text',`value="${esc(s.name)}"`)}${fld('contact','Contact person','text',`value="${esc(s.contact)}"`)}${fld('phone','Phone','tel',`value="${esc(s.phone)}"`)}<button class="btn wide">Save changes</button></form></details>`;
return{k:'Supplier',title:esc(s.name),body}};

/* A5 records, users, form submits, wiring */
const rTab=(k,r)=>k==='all'||(k==='retail'?r.t==='Customer sale':k==='trade'?r.t==='Wholesale sale':r.t==='Supplier purchase');
function recRows(){return[...S.orders.map(o=>({ts:o.ts,ref:o.id,t:o.type==='trade'?'Wholesale sale':'Customer sale',who:o.party,amt:tot(o),st:o.status,open:'order:'+o.id})),...S.purchases.map(p=>({ts:p.ts,ref:p.id,t:'Supplier purchase',who:sname(p.s)||'(removed)',amt:-p.q*p.cost,st:p.status,open:'po:'+p.id}))].sort((a,b)=>b.ts-a.ts)}
function recPool(){const s=AS.rec,k=s.q.trim().toLowerCase();return recRows().filter(r=>inR(r.ts,s.range)&&(!k||(r.ref+' '+r.who+' '+r.t).toLowerCase().includes(k)))}
const recList=()=>recPool().filter(r=>rTab(AS.rec.tab,r));
function recPage(){const s=AS.rec;return adph('Transaction records','Every sale and purchase in one place.',`<button class="btn ghost" onclick="adCsv()">Download CSV</button>`)+`<div class="stats" id="adkpi">${recKpi()}</div><div id="adtabs">${recTabs()}</div><div class="ad-bar"><label class="ad-search"><span class="sr">Search</span>${SRCH}<input type="search" placeholder="Search reference, customer or supplier" value="${esc(s.q)}" oninput="adRQ(this.value)" autocomplete="off"></label><select aria-label="Date" onchange="adR('range',this.value)">${opt([['all','All time'],['today','Today'],['7','Last 7 days'],['30','Last 30 days']],x=>x,s.range)}</select></div><div id="adres">${recRes()}</div>`}
function recKpi(){const v=recRows().filter(r=>inR(r.ts,AS.rec.range)&&r.st!=='Cancelled'),i=v.filter(r=>r.amt>0).reduce((a,r)=>a+r.amt,0),o=-v.filter(r=>r.amt<0).reduce((a,r)=>a+r.amt,0);return st2('📈','Money in',peso(i))+st2('📉','Money out',peso(o))+st2('⚖️','Net',peso(i-o))}
function recTabs(){const s=AS.rec,p=recPool();return `<div class="ad-tabs">${[['all','All'],['retail','Customer sales'],['trade','Wholesale'],['buy','Purchases']].map(([k,l])=>`<button aria-pressed="${s.tab===k}" onclick="adR('tab','${k}')">${l}<span class="n">${p.filter(r=>rTab(k,r)).length}</span></button>`).join('')}</div>`}
function recRes(){const s=AS.rec,r=recList(),show=r.slice(0,s.n);if(!r.length)return `<div class="card ad-empty"><span class="ic big">${ICO('📈')}</span><b>No records found</b><span>Try another word or a longer date range.</span></div>`;let last='';
return `<div class="ad-sum"><span>Showing ${show.length} of ${pl(r.length,'record')}</span></div><div class="ad-list">${show.map(x=>{let g='';const d=dayLbl(x.ts);if(d!==last){last=d;g=`<div class="ad-gh">${d}<span>${show.filter(y=>dayLbl(y.ts)===d).length}</span></div>`}return g+`<div class="ad-row rec" data-open="${x.open}" tabindex="0" role="button" aria-label="Open ${x.ref}"><span class="ic ad-rec-ic">${ICO(x.amt<0?'🚚':x.t==='Wholesale sale'?'🏪':'🛍️')}</span><div class="ad-who"><b>${x.t}</b><small>${esc(x.who)} · ${x.ref}</small></div><b class="ad-amt ${x.amt<0?'bad':''}">${x.amt<0?'−':'+'}${peso(Math.abs(x.amt))}</b>${pill(x.st)}</div>`}).join('')}${r.length>show.length?`<button class="ad-more-btn" onclick="AS.rec.n+=25;set_('adres',recRes())">Show more</button>`:''}</div>`}
function recRefresh(){set_('adkpi',recKpi());set_('adtabs',recTabs());set_('adres',recRes())}
function adR(k,v){AS.rec[k]=v;AS.rec.n=25;recRefresh()}
function adRQ(v){AS.rec.q=v;AS.rec.n=25;set_('adtabs',recTabs());set_('adres',recRes())}
function adCsv(){const q=v=>`"${String(v).replace(/"/g,'""')}"`,rows=recList(),csv=[['Date','Reference','Type','Party','Amount (PHP)','Status'],...rows.map(r=>[new Date(r.ts).toISOString().slice(0,10),r.ref,r.t,r.who,r.amt.toFixed(2),r.st])].map(r=>r.map(q).join(',')).join('\r\n');
const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['﻿'+csv],{type:'text/csv'}));a.download='colmans-records.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),2000);adNote(`${pl(rows.length,'record')} exported.`)}

/* users (admin only) */
const RD={customer:'Can shop and track orders',staff:'Manages orders, stock and purchasing',admin:'Full access, including users'},RP={admin:'info',staff:'ok',customer:'mute'};
const usrTab=(k,u)=>k==='all'||u.role===k;
function usrPool(){const k=AS.usr.q.trim().toLowerCase();return S.users.filter(u=>!k||(u.name+' '+u.user).toLowerCase().includes(k))}
function usrPage(){return adph('Users','Control who can shop, manage stock or run the system.',`<button class="btn" onclick="adOpen('nusr')">＋ Add user</button>`)+`<div id="adtabs">${usrTabs()}</div><div class="ad-bar"><label class="ad-search"><span class="sr">Search</span>${SRCH}<input type="search" placeholder="Search name or username" value="${esc(AS.usr.q)}" oninput="AS.usr.q=this.value;usrRefresh()" autocomplete="off"></label></div><div id="adres">${usrRes()}</div>`}
function usrTabs(){const s=AS.usr,p=usrPool();return `<div class="ad-tabs">${[['all','Everyone'],['admin','Admins'],['staff','Staff'],['customer','Customers']].map(([k,l])=>`<button aria-pressed="${s.tab===k}" onclick="AS.usr.tab='${k}';usrRefresh()">${l}<span class="n">${p.filter(u=>usrTab(k,u)).length}</span></button>`).join('')}</div>`}
function usrRes(){const r=usrPool().filter(u=>usrTab(AS.usr.tab,u));return r.length?`<div class="cardgrid">${r.map(u=>{const n=S.orders.filter(o=>o.type==='retail'&&o.party===u.name).length;return `<div class="card ad-click" data-open="usr:${u.id}" tabindex="0" role="button" aria-label="Open ${esc(u.name)}"><div class="row">${av(u.name)}<div class="grow"><b>${esc(u.name)}${u.id===S.me?' <small style="display:inline">(you)</small>':''}</b><small>${esc(u.user)}${u.role==='customer'?' · '+pl(n,'order'):''}</small></div><span class="pill ${RP[u.role]}">${u.role}</span></div><small>${RD[u.role]}</small><select aria-label="Role of ${esc(u.name)}" ${u.id===S.me?'disabled title="You cannot change your own role"':''} onchange="adRole('${u.id}',this.value)">${opt(['customer','staff','admin'],x=>[x,x],u.role)}</select></div>`}).join('')}</div>`:`<div class="card ad-empty"><span class="ic big">${ICO('🛍')}</span><b>No users found</b><span>Try another name.</span></div>`}
function usrRefresh(){set_('adtabs',usrTabs());set_('adres',usrRes())}
function adRole(id,r){const u=S.users.find(x=>x.id===id);if(!u||u.role===r)return;if(u.id===S.me&&r!=='admin'){adNote('You cannot remove your own admin access.');adRefresh();return}
if(u.role==='admin'&&r!=='admin'&&S.users.filter(x=>x.role==='admin').length<2){adNote('Keep at least one admin.');adRefresh();return}const was=u.role;u.role=r;save();adNote(`${u.name} is now ${r}.`,()=>{u.role=was;save();adRefresh()});adRefresh()}
DR.nusr=()=>({k:'Users',title:'Add a user',body:`<form class="ad-fg" onsubmit="event.preventDefault();adSub('usr',Object.fromEntries(new FormData(this)))">${fld('name','Full name','text')}${fld('user','Username or email','text','autocomplete="off"')}${fld('pw','Password (6+ characters)','password','minlength="6" autocomplete="new-password"')}${sel('role','Role',opt(['customer','staff','admin'],r=>[r,`${r[0].toUpperCase()+r.slice(1)} · ${RD[r]}`],'staff'))}<button class="btn wide">Add user</button></form>`});
DR.usr=id=>{const u=S.users.find(x=>x.id===id);if(!u)return null;const os=S.orders.filter(o=>o.type==='retail'&&o.party===u.name).sort((a,b)=>b.ts-a.ts).slice(0,6),me_=u.id===S.me;
const body=`<div class="row"><div class="ad-who2">${av(u.name)}<div><b>${esc(u.name)}${me_?' (you)':''}</b><small>${esc(u.user)}</small></div></div><span class="pill ${RP[u.role]}">${u.role}</span></div>
<label class="ad-f">Role<select ${me_?'disabled':''} onchange="adRole('${id}',this.value)">${opt(['customer','staff','admin'],x=>[x,x[0].toUpperCase()+x.slice(1)],u.role)}</select></label><p class="ad-hint">${me_?'You cannot change your own role.':RD[u.role]+'.'}</p>
<details class="ad-det"><summary>Set a new password</summary><form class="ad-fg" onsubmit="event.preventDefault();adSub('pw',Object.fromEntries(new FormData(this)),'${id}')">${fld('pw','New password (6+ characters)','password','minlength="6" autocomplete="new-password"')}<button class="btn wide">Save password</button></form></details>
${u.role==='customer'?`<div class="ad-sec">Orders</div>${os.length?`<div class="ad-lines">${os.map(o=>`<div class="ad-li" data-open="order:${o.id}" tabindex="0" role="button"><div class="grow"><b>${o.id}</b><small>${ago(o.ts)} · ${peso(tot(o))}</small></div>${pill(o.status)}</div>`).join('')}</div>`:'<p class="mute">No orders yet.</p>'}`:''}`;
return{k:'User',title:esc(u.name),body}};

/* every form in the panels ends up here */
async function adSub(k,d,id){const now=Date.now();
if(k==='po'){const q=Math.floor(+d.q),c=+d.cost,pr=prod(d.p);if(!pr||!(q>=1)||d.cost===''||!(c>=0))return adNote('Enter a quantity and a unit cost.');const po={id:nid('PO'),s:d.s,p:d.p,q,cost:c,status:'Ordered',ts:now};S.purchases.unshift(po);save();if(drw&&drw.t==='npo')adClose();adNote(`${po.id} recorded: ${q} × ${pr.name}.`);adRefresh();return}
if(k==='tr'){const p=prod(d.p),q=Math.floor(+d.q),dd=Math.min(90,Math.max(0,+d.d||0));if(!p||!(q>=1))return adNote('Enter a quantity of 1 or more.');if(q>p.stock)return adNote(`Only ${p.stock} of ${p.name} in stock. Lower the quantity.`);
p.stock-=q;const o={id:nid('TRD'),type:'trade',party:d.b.trim(),items:[{p:p.id,q,pr:Math.round(p.price*(100-dd))/100}],status:'Pending',ts:now,log:[{s:'Pending',ts:now}]};S.orders.unshift(o);save();adClose();adNote(`${o.id} recorded for ${o.party}.`);adRefresh();return}
if(k==='prod'){S.products.push({id:'p'+now,e:ci(d.cat)[1],was:0,name:d.name.trim(),cat:d.cat,price:+d.price,stock:Math.floor(+d.stock),min:Math.floor(+d.min)});save();adClose();adNote('Product added.');adRefresh();return}
if(k==='prodEdit'){const p=prod(id);if(!p)return;const w=d.was===''?0:+d.was;Object.assign(p,{name:d.name.trim(),cat:d.cat,price:+d.price,was:w>+d.price?w:0,min:Math.floor(+d.min)});save();adNote('Changes saved.');adRefresh();return}
if(k==='sup'){S.suppliers.push({id:'s'+now,name:d.name.trim(),contact:d.contact.trim(),phone:d.phone.trim()});save();adClose();adNote('Supplier added.');adRefresh();return}
if(k==='supEdit'){const s=S.suppliers.find(x=>x.id===id);if(!s)return;Object.assign(s,{name:d.name.trim(),contact:d.contact.trim(),phone:d.phone.trim()});save();adNote('Changes saved.');adRefresh();return}
if(me().role!=='admin')return;
if(k==='usr'){const u=d.user.trim().toLowerCase();if(S.users.some(x=>x.user===u))return adNote('That username is already taken.');S.users.push({id:'u'+now,name:d.name.trim(),user:u,pw:await sha(d.pw),role:d.role});save();adClose();adNote('User added.');adRefresh();return}
if(k==='pw'){const u=S.users.find(x=>x.id===id);if(!u)return;u.pw=await sha(d.pw);save();adNote(`Password updated for ${u.name}.`);adDraw()}}

/* wiring: pages, refresh hooks */
Object.assign(V,{orders:()=>wsPage('o'),trade:()=>wsPage('t'),inventory:invPage,suppliers:supPage,purchasing:poPage,records:recPage,users:usrPage});
const wsLive=w=>{set_('adtabs',wsTabs(w));set_('adres',wsRes(w));adBulk()};
Object.assign(PG,{dashboard:{refresh:()=>go()},orders:{refresh:()=>wsLive('o')},trade:{refresh:()=>{set_('adkpi',tradeKpi());wsLive('t')}},inventory:{refresh:invRefresh},purchasing:{refresh:poRefresh},suppliers:{refresh:()=>set_('adres',supRes())},records:{refresh:recRefresh},users:{refresh:usrRefresh}});

/* first run: mix sample orders in so lists, search and bulk actions can be tried right away */
if(!S.smpDone){S.orders.push(...mkSample(S,34));S.orders.sort((a,b)=>b.ts-a.ts);S.smpDone=1;save()}

/* ===== script 3: main-3 ===== */
go();

/* ===== script 4: main-4 ===== */
/* hero choreography: one passive scroll listener -> one rAF -> a few CSS variables (--p pin progress, --q cover progress) + snow */
(()=>{const rm=FX.rm;let h,hh=0,hd,ho,af,afTop=0,raf=0,lastY=0,V=0;
const clamp=(v,a=0,b=1)=>Math.min(b,Math.max(a,v)),Y=()=>window.pageYOffset||document.documentElement.scrollTop||document.body.scrollTop||0;
const find=()=>{hd=document.querySelector('header');document.documentElement.style.setProperty('--hdr',(hd?hd.offsetHeight:65)+'px');h=document.getElementById('hero');hh=h?h.offsetHeight:0;ho=document.querySelector('.hold');af=document.querySelector('.after');afTop=af?af.getBoundingClientRect().top+Y():0};
const bar=document.createElement('i');bar.id='pgbar';bar.setAttribute('aria-hidden','true');document.body.appendChild(bar);
const upd=()=>{raf=0;if(!h||!h.isConnected)find();const y=Y(),dh=document.documentElement.scrollHeight-innerHeight;bar.style.transform='scaleX('+(dh>0?clamp(y/dh):0).toFixed(4)+')';V+=((y-lastY)-V)*.5;lastY=y;if(!h)return;const hdr=hd?hd.offsetHeight:65,p=clamp(y/((ho?ho.offsetHeight:hh)*.72)),q=af?clamp((y+innerHeight-afTop)/(innerHeight-hdr)):0;h.style.setProperty('--p',p.toFixed(4));h.style.setProperty('--q',q.toFixed(4));h.style.setProperty('--hh',hh+'px');const cb=h.querySelector('.cta');if(cb&&af)h.classList.toggle('cta-gone',af.getBoundingClientRect().top<cb.getBoundingClientRect().bottom+8)};
const req=()=>{if(!raf)raf=requestAnimationFrame(upd)};
addEventListener('scroll',req,{passive:true,capture:true});addEventListener('resize',()=>{h=null;cv=null;req()});
const app=document.getElementById('app');if(app)new MutationObserver(()=>{h=null;req()}).observe(app,{childList:true});
/* snow: soft flakes in depth layers; they streak with scroll speed and pause when hidden, covered or reduced-motion */
let cv=null,cx,W=0,H=0,fl=[],last=0;
const initSnow=()=>{cv=h&&h.querySelector('.L-snow');if(!cv)return;const r=cv.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,1.5);W=r.width;H=r.height;cv.width=W*d;cv.height=H*d;cx=cv.getContext('2d');cx.setTransform(d,0,0,d,0,0);fl=Array.from({length:W<700?34:72},()=>({x:Math.random()*W,y:Math.random()*H,z:.25+Math.random()*.75,s:Math.random()*6}))};
const tick=t=>{requestAnimationFrame(tick);V*=.9;if(document.hidden||!h||!h.isConnected||+h.style.getPropertyValue('--q')>.97||!FX.on('snow'))return;if(!cv||!cv.isConnected){initSnow();if(!cv)return}const dt=Math.min(.05,(t-last)/1000||0);last=t;cx.clearRect(0,0,W,H);cx.fillStyle='#fff';for(const f of fl){const calm=rm.matches;f.y+=(16+46*f.z)*dt*(calm?.5:1)-(calm?0:V*f.z*.9);f.x+=Math.sin(t*.0006+f.s)*9*dt*f.z*(calm?.5:1);if(f.y>H+4){f.y=-4;f.x=Math.random()*W}else if(f.y<-4){f.y=H+4;f.x=Math.random()*W}if(f.x>W+4)f.x=-4;else if(f.x<-4)f.x=W+4;cx.globalAlpha=.22+.6*f.z;cx.beginPath();cx.arc(f.x,f.y,.7+2*f.z,0,6.2832);cx.fill()}};
requestAnimationFrame(tick);req()})();

