/* page helpers: view marker, "how this page works" guides, form hints, inventory search */
(()=>{const HOW={
shop:['Browse a category or search by name.','Tap + on an item to add it to your cart.','Open the cart and check out. You will be asked to sign in.','Follow your order in My orders.'],
mine:['A new order starts as Pending.','Staff move it to Processing, then Ready for pickup or delivery.','It shows Completed once you have it.','You can cancel it only while it is still Pending.'],
orders:['The tabs split orders by stage. "Needs action" is everything not yet completed.','Search by order number, customer or item. Narrow by date, or change the sort.','Click an order to see its items and history. The red button moves it to the next stage.','Tick several orders to move them together. Use Undo if you tap the wrong one.'],
inventory:['Click a product to open it. Fix the count, restock it or edit its price there.','Low stock means the item reached its reorder level. Press Reorder to start a purchase order.','Switch between List and Cards. Filter by category or stock level.'],
suppliers:['Click a supplier to see what you bought from them and their contact details.','Press New purchase order on a card to start an order with that supplier.'],
purchasing:['Needs restocking lists items at or below their reorder level. Press Reorder to order them.','On order shows deliveries still to come. Press Mark received when the goods arrive. Stock goes up automatically.','Click any order to see the details or cancel it.'],
trade:['Wholesale means selling in bulk to another business at a discount.','Press New wholesale order, fill in the business, product, quantity and discount.','Process wholesale orders the same way as customer orders.'],
records:['Money in is customer and wholesale sales. Money out is supplier purchases.','Search, filter by date or type, then press Download CSV to save the list.','Click a record to open the order or purchase behind it.'],
users:['Customers can shop and track their orders.','Staff manage orders, stock and purchasing.','Admins can do everything, including managing users. Click a user to change their role or password.']};
const enh=()=>{const m=document.querySelector('main');if(!m)return;const cur=document.querySelector('header nav button[aria-current]'),v=cur?((cur.getAttribute('onclick')||'').match(/nav\('(\w+)'\)/)||[])[1]:'';m.dataset.v=v||'';
const ph=m.querySelector('.ph'),s=HOW[v];
if(ph&&s&&!m.querySelector('.how')){let st=null;try{st=localStorage.getItem('cm-how-'+v)}catch(e){}
const d=document.createElement('details');d.className='how';d.open=st===null?(innerWidth>800&&(v==='shop'||v==='mine')):st==='1';d.innerHTML='<summary>How this page works</summary><ol>'+s.map(x=>'<li>'+x+'</li>').join('')+'</ol>';
d.addEventListener('toggle',()=>{try{localStorage.setItem('cm-how-'+v,d.open?'1':'0')}catch(e){}});ph.after(d)}
m.querySelectorAll('label input:not([placeholder])').forEach(i=>{if(!/^(text|number|tel|email)$/.test(i.type||'text'))return;const t=(i.closest('label').textContent||'').trim().replace(/\s*\(.*\)\s*$/,'');if(t)i.placeholder='Enter '+t.toLowerCase()});
};
const app=document.getElementById('app');if(app)new MutationObserver(enh).observe(app,{childList:true});enh()})();

