/* ===== script 13: doors ===== */
/* ===== Sliding-door transition for the login page =====
   Sign in  -> left half slides in from the left, right half from the right, they meet in the middle and puff a little smoke.
   Back to shop (or after a successful sign-in) -> the two halves slide apart again, like a sliding door opening onto the page. */
(()=>{
const DUR=900,EASE='cubic-bezier(.55,0,.25,1)',RM=FX.rm;
const q=s=>document.querySelector(s),rnd=(a,b)=>a+Math.random()*(b-a);
const mk=(css,cls)=>{const d=document.createElement('div');if(cls)d.className=cls;d.style.cssText=css||'';return d};
let live=[],nodes=[],timers=[],wasLogin=false;

function cancel(){
  live.forEach(a=>{try{a.finish()}catch(e){}});live=[];
  timers.forEach(clearTimeout);timers=[];
  nodes.forEach(n=>n.remove());nodes=[];
  const a=q('.auth');if(a){a.style.position='';a.style.zIndex=''}
}

/* a frozen picture of the page we are leaving, shown behind the doors while they slide in */
function snap(){
  try{
    const app=q('#app');if(!app)return null;
    const y=scrollY,root=mk('position:fixed;inset:0;z-index:8999;pointer-events:none;background:var(--bg)','dstatic');
    const sc=mk('position:absolute;inset:0;overflow:hidden'),inner=mk('display:flex;flex-direction:column;min-height:100vh;width:100%');
    [...app.children].forEach(c=>{if(c.matches&&c.matches('.drawer,.scrim'))return;const k=c.cloneNode(true);k.style.flexShrink='0';inner.appendChild(k)});
    sc.appendChild(inner);root.appendChild(sc);
    const dim=mk('position:absolute;inset:0;background:#000;opacity:0');root.appendChild(dim);
    return {root,sc,dim,y};
  }catch(e){return null}
}

/* a copy of the login page, used as the doors while they slide away */
function lift(){
  const a=q('.auth');if(!a)return null;
  const k=a.cloneNode(true),o=a.querySelectorAll('input'),c=k.querySelectorAll('input');
  o.forEach((i,n)=>c[n]&&c[n].setAttribute('value',i.value));
  return k;
}

const kfIn=side=>[
  {transform:`translateX(${side*102}%)`,boxShadow:`${-side*16}px 0 44px rgba(0,0,0,.6)`,easing:EASE},
  {transform:`translateX(${-side*1.4}%)`,boxShadow:`${-side*10}px 0 30px rgba(0,0,0,.45)`,offset:.87,easing:'ease-out'},
  {transform:'translateX(0)',boxShadow:'0 0 0 rgba(0,0,0,0)'}
];

/* doors CLOSE: login page arrives */
function close(s){
  const auth=q('.auth'),ap=q('.auth .ap'),af=q('.auth .afw');
  if(!auth||!ap||!af)return;
  if(s){document.body.appendChild(s.root);nodes.push(s.root);s.sc.scrollTop=s.y;
    live.push(s.dim.animate([{opacity:0},{opacity:.75}],{duration:DUR,easing:'ease-in',fill:'forwards'}))}
  auth.style.position='relative';auth.style.zIndex='9000';
  const a1=ap.animate(kfIn(-1),{duration:DUR}),a2=af.animate(kfIn(1),{duration:DUR});
  live.push(a1,a2);
  timers.push(setTimeout(()=>smoke(auth,ap,af),DUR*.87));
  Promise.all([a1.finished,a2.finished]).then(()=>{if(s)s.root.remove();auth.style.position='';auth.style.zIndex=''}).catch(()=>{});
}

/* doors OPEN: login page leaves, the page behind (already drawn underneath) is revealed */
function open(k){
  if(!k)return;
  const ov=mk('position:fixed;inset:0;z-index:9999;pointer-events:none;overflow:hidden','dstatic');
  k.style.minHeight='0';k.style.height='100%';
  ov.appendChild(k);document.body.appendChild(ov);nodes.push(ov);
  const ap=k.querySelector('.ap'),af=k.querySelector('.afw');
  const kf=side=>[{transform:'translateX(0)',boxShadow:'0 0 0 rgba(0,0,0,0)'},{transform:`translateX(${side*102}%)`,boxShadow:`${-side*16}px 0 44px rgba(0,0,0,.6)`}];
  const o={duration:DUR*.85,easing:'cubic-bezier(.6,0,.3,1)',fill:'forwards'};
  const a1=ap.animate(kf(-1),o),a2=af.animate(kf(1),o);live.push(a1,a2);
  Promise.all([a1.finished,a2.finished]).then(()=>ov.remove()).catch(()=>{});
}

/* the little puff of smoke + flash where the two doors meet */
function smoke(auth,ap,af){
  if(!ap||!af||!ap.isConnected)return;
  const vw=innerWidth,vh=innerHeight,side=af.offsetLeft>=ap.offsetLeft+ap.offsetWidth-2; // true = doors side by side
  const sx=ap.offsetLeft+ap.offsetWidth,sy=ap.offsetTop+ap.offsetHeight-scrollY;
  const box=mk('position:fixed;inset:0;z-index:9500;pointer-events:none;overflow:hidden');box.id='doorsmoke';
  const n=vw<700?16:30;
  for(let i=0;i<n;i++){
    const s=rnd(vw<700?90:110,vw<700?210:300),h=s*rnd(.65,1.05);
    // most smoke gathers in the lower two-thirds of the seam, like dust thrown up by a heavy door
    const x=side?sx+rnd(-18,18):rnd(0,vw),y=side?vh*(.12+.95*Math.pow(Math.random(),.7)):sy+rnd(-12,12);
    const p=mk(`position:absolute;left:${x-s/2}px;top:${y-h/2}px;width:${s}px;height:${h}px;border-radius:50%;background:radial-gradient(closest-side,rgba(236,240,250,.68) 0%,rgba(216,222,236,.4) 32%,rgba(196,204,220,.13) 58%,rgba(190,198,214,0) 100%);filter:blur(9px);opacity:0;will-change:transform,opacity`);
    const dir=Math.random()<.5?-1:1,dx=rnd(50,210)*dir,dy=rnd(30,140),rot=rnd(-35,35);
    p.animate([{opacity:0,transform:'translate(0,0) scale(.3) rotate(0deg)'},{opacity:rnd(.6,.9),transform:`translate(${dx*.3}px,${-dy*.35}px) scale(.85) rotate(${rot*.4}deg)`,offset:.25},{opacity:0,transform:`translate(${dx}px,${-dy}px) scale(1.9) rotate(${rot}deg)`}],
      {duration:rnd(1200,2000),delay:rnd(0,200),easing:'cubic-bezier(.15,.6,.3,1)',fill:'both'});
    box.appendChild(p);
  }
  const fl=mk(side?`position:absolute;left:${sx-1}px;top:0;width:2px;height:100%;background:linear-gradient(transparent,#fff 25%,#fff 75%,transparent);box-shadow:0 0 26px 7px rgba(255,255,255,.4)`
                  :`position:absolute;top:${sy-1}px;left:0;height:2px;width:100%;background:linear-gradient(90deg,transparent,#fff 25%,#fff 75%,transparent);box-shadow:0 0 26px 7px rgba(255,255,255,.4)`);
  fl.animate([{opacity:.95},{opacity:0}],{duration:520,easing:'ease-out',fill:'forwards'});
  box.appendChild(fl);
  document.body.appendChild(box);
  if(!RM.matches)auth.animate([{transform:'translateX(0)'},{transform:'translateX(-3px)'},{transform:'translateX(3px)'},{transform:'translateX(-2px)'},{transform:'translateX(1px)'},{transform:'none'}],{duration:240,easing:'ease-out'});
  setTimeout(()=>box.remove(),2600);
}

/* hook the page's single render function */
const go0=window.go;
window.go=function(){
  const au=view==='login'&&me().role==='guest';
  cancel();
  const enter=au&&!wasLogin,leave=!au&&wasLogin;
  const s=enter?snap():null,k=leave?lift():null;
  const r=go0.apply(this,arguments);
  wasLogin=au;
  if(enter)close(s);else if(leave)open(k);
  return r;
};
})();

/* ===== script 14: sup-posters ===== */
/* ===== Supplier posters ===== */
const SUPPOSTER={void:"data:image/webp;base64,",ut:"data:image/webp;base64,",metro:"data:image/webp;base64,",herock:"data:image/webp;base64,"};
const SUPORDER=[['void',/\bvoid\b/i],['ut',/urban\s*thread/i],['metro',/metro/i],['herock',/herock/i]];
const supKey=s=>{const m=SUPORDER.find(x=>x[1].test(s.name||''));return m?m[0]:null};
const supTh=s=>{const k=supKey(s);return k?`<div class="sup-th"><img src="${SUPPOSTER[k]}" alt="${esc(s.name)} poster" loading="lazy" decoding="async"></div>`:''};
let spsLast=0,spsPaused=false;
function supSlider(){
  const l=SUPORDER.map(x=>S.suppliers.find(s=>supKey(s)===x[0])).filter(Boolean);
  if(!l.length)return '';
  return `<section class="sps" aria-roledescription="carousel" aria-label="Supplier posters"><div class="sps-track" id="spc">${l.map(s=>{const u=SUPPOSTER[supKey(s)];return `<div class="sps-s" data-open="sup:${s.id}" tabindex="0" role="button" aria-roledescription="slide" aria-label="Open ${esc(s.name)}"><i class="bg" style="background-image:url(${u})"></i><img src="${u}" alt="${esc(s.name)} poster"><span class="sps-tag">Supplier · ${esc(s.name)}</span><span class="sps-go">View supplier ›</span></div>`}).join('')}</div>${l.length>1?'<button class="sps-nav p" data-spn="-1" aria-label="Previous poster">‹</button><button class="sps-nav n" data-spn="1" aria-label="Next poster">›</button>':''}<div class="sps-bar">${l.map((s,i)=>`<button ${i?'':'aria-current="true"'} data-spi="${i}">${esc(s.name)}</button>`).join('')}${l.length>1?`<button class="sps-pp" data-spp aria-label="${spsPaused?'Play':'Pause'} slideshow">${spsPaused?'PLAY':'PAUSE'}</button>`:''}</div></section>`;
}
(()=>{
  const trk=()=>document.getElementById('spc'),idx=t=>Math.round(t.scrollLeft/Math.max(1,t.clientWidth));
  const go=i=>{const t=trk();if(!t)return;const n=t.children.length;i=(i+n)%n;t.scrollTo({left:i*t.clientWidth,behavior:'smooth'})};
  const mark=()=>{const t=trk();if(!t)return;const i=idx(t);document.querySelectorAll('.sps-bar [data-spi]').forEach((b,j)=>j===i?b.setAttribute('aria-current','true'):b.removeAttribute('aria-current'))};
  document.addEventListener('scroll',e=>{if(e.target&&e.target.id==='spc')mark()},true);
  document.addEventListener('click',e=>{
    const b=e.target.closest&&e.target.closest('[data-spn],[data-spi],[data-spp]');if(!b)return;
    spsLast=Date.now();const t=trk();if(!t)return;
    if(b.dataset.spn)go(idx(t)+ +b.dataset.spn);
    else if(b.dataset.spi!==undefined)go(+b.dataset.spi);
    else{spsPaused=!spsPaused;b.textContent=spsPaused?'PLAY':'PAUSE';b.setAttribute('aria-label',(spsPaused?'Play':'Pause')+' slideshow')}
  });
  ['pointerdown','keydown','wheel','touchstart'].forEach(ev=>document.addEventListener(ev,e=>{if(e.target&&e.target.closest&&e.target.closest('.sps'))spsLast=Date.now()},{passive:true,capture:true}));
  /* auto-slide every 5s; waits while you hover/touch it, when the tab is hidden, or after you press Pause */
  setInterval(()=>{const t=trk();if(!t||spsPaused||document.hidden||t.children.length<2||Date.now()-spsLast<6000||t.matches(':hover')||t.contains(document.activeElement))return;go(idx(t)+1)},5000);
})();

/* ===== Home hero auto-slide =====
   Moves to the next product every 6 seconds. It is driven by this timer (not by the CSS progress bar), so it also works when the
   device has "reduce motion" turned on. Pauses while the mouse is over the hero or the tab is hidden; clicking a card restarts the 6s. */
(()=>{let last=performance.now();
  setInterval(()=>{
    const now=performance.now(),dt=Math.min(now-last,500);last=now;
    const h=document.getElementById('hero');
    if(!h||!h.isConnected||h.closest('#doorbg')||document.hidden||h.matches(':hover'))return;
    window.__hiEl=(window.__hiEl||0)+dt;
    if(window.__hiEl>=6000)setHi((hi+1)%HL().length);
  },100);
})();


/* ===== Light / dark switch animation =====
   Circle reveal that grows from the toggle button (View Transitions API).
   Browsers without it get a soft colour fade instead. Reduced-motion users get an instant switch. */
function themeSwap(apply,ev){
  const root=document.documentElement;
  if(FX.rm.matches){apply();return}
  const t=ev&&ev.currentTarget,btn=t&&t.getBoundingClientRect?t:document.querySelector('.tgl');
  if(btn&&btn.animate)btn.animate([{rotate:'0deg'},{rotate:'360deg'}],{duration:600,easing:'cubic-bezier(.2,.8,.2,1)'});
  if(typeof document.startViewTransition==='function'){
    const r=btn?btn.getBoundingClientRect():null,
      x=r?r.left+r.width/2:innerWidth-40,y=r?r.top+r.height/2:40,
      end=Math.hypot(Math.max(x,innerWidth-x),Math.max(y,innerHeight-y));
    root.classList.add('theme-vt');
    let vt;
    try{vt=document.startViewTransition(apply)}catch(e){root.classList.remove('theme-vt');apply();return}
    vt.ready.then(()=>root.animate(
      {clipPath:[`circle(0px at ${x}px ${y}px)`,`circle(${end}px at ${x}px ${y}px)`]},
      {duration:700,easing:'cubic-bezier(.4,0,.2,1)',pseudoElement:'::view-transition-new(root)'})).catch(()=>{});
    vt.finished.finally(()=>root.classList.remove('theme-vt'));
    return;
  }
  root.classList.add('theme-fade');
  apply();
  clearTimeout(themeSwap.t);
  themeSwap.t=setTimeout(()=>root.classList.remove('theme-fade'),650);
}

/* ===== Shop: on phones the category chips scroll sideways, so keep the active one in view after a re-render ===== */
(()=>{
  const reveal=()=>document.querySelectorAll('main .sec .chips').forEach(c=>{
    const a=c.querySelector('[aria-pressed=true]');
    if(!a||c.scrollWidth<=c.clientWidth)return;
    const x=a.getBoundingClientRect().left-c.getBoundingClientRect().left+c.scrollLeft;
    c.scrollLeft=Math.max(0,x-(c.clientWidth-a.offsetWidth)/2);
  });
  /* the page tags <main data-v="shop"> a moment after each render, which is when the chips become a sideways row */
  const app=document.getElementById('app');
  if(app&&window.MutationObserver)new MutationObserver(reveal).observe(app,{subtree:true,attributes:true,attributeFilter:['data-v']});
})();

/* ===== script 15: display settings panel ===== */
/* The settings button in the header (next to Sign in) opens this panel. Choices are stored by FX (script 0). */
(()=>{
const ROWS=[
  ['anim','Animations','Entrances, fades, slides and transitions'],
  ['hero','Scroll effects','Parallax and zoom while you scroll'],
  ['mouse','Mouse effects','Cursor glow, 3D tilt and hover lifts'],
  ['snow','Falling snow','Particles over the hero'],
  ['glow','Blur & glow','Frosted blur, soft glows and shadows'],
  ['art','Background artwork','Hero scenery and the rough title texture']];
const PRE=[['full','Full','Everything on'],['reduced','Reduced','No motion'],['minimal','Minimal','Lightest']];
let p=null,open=false;
const build=()=>{
  p=document.createElement('div');p.id='fxp';p.className='fxp';p.hidden=true;
  p.setAttribute('role','dialog');p.setAttribute('aria-labelledby','fxt');
  p.innerHTML=`<div class="fxh"><b id="fxt">Display &amp; effects</b><button type="button" class="fxx" data-fxc aria-label="Close settings">×</button></div>
<p class="fxs">Turn graphics and effects down if the site feels slow or busy. Saved on this device.</p>
<div class="fxseg" role="group" aria-label="Quick presets">${PRE.map(([k,t,d])=>`<button type="button" data-fxp="${k}" aria-pressed="false"><b>${t}</b><small>${d}</small></button>`).join('')}</div>
<div class="fxlist">${ROWS.map(([k,t,d])=>`<label class="fxrow"><span class="fxl"><b>${t}</b><small>${d}</small></span><input type="checkbox" role="switch" data-fxk="${k}"><i class="fxsw" aria-hidden="true"></i></label>`).join('')}</div>
<div class="fxf"><span data-fxs></span><button type="button" data-fxr>Reset to Full</button></div>`;
  document.body.appendChild(p);
  p.addEventListener('click',e=>{
    const t=e.target.closest('[data-fxp],[data-fxr],[data-fxc]');if(!t)return;
    if(t.dataset.fxp)FX.preset(t.dataset.fxp);
    else if(t.hasAttribute('data-fxr'))FX.preset('full');
    else close(true)});
  p.addEventListener('change',e=>{const k=e.target.dataset&&e.target.dataset.fxk;if(k)FX.set(k,e.target.checked)});
};
const sync=()=>{
  if(!p)return;
  const s=FX.get(),cur=FX.current();
  p.querySelectorAll('[data-fxk]').forEach(i=>{i.checked=!!s[i.dataset.fxk]});
  p.querySelectorAll('[data-fxp]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.fxp===cur?'true':'false'));
  p.querySelector('[data-fxs]').textContent=cur==='custom'?'Custom mix':cur[0].toUpperCase()+cur.slice(1)+' preset';
};
const place=()=>{
  if(!open)return;
  const h=document.querySelector('header'),top=Math.max(8,Math.round((h?h.getBoundingClientRect().bottom:60)+8));
  p.style.top=top+'px';p.style.maxHeight=Math.max(240,innerHeight-top-12)+'px';
};
const mark=()=>document.querySelectorAll('.fxbtn').forEach(b=>b.setAttribute('aria-expanded',open?'true':'false'));
const openP=()=>{
  if(!p)build();
  open=true;sync();p.hidden=false;place();mark();
  const f=p.querySelector('[data-fxp][aria-pressed="true"]')||p.querySelector('button');
  if(f)f.focus({preventScroll:true});
};
const close=back=>{
  if(!open)return;
  open=false;p.hidden=true;mark();
  if(back){const b=document.querySelector('.fxbtn');if(b)b.focus({preventScroll:true})}
};
window.fxToggle=()=>{open?close(true):openP()};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&open){e.stopPropagation();close(true)}},true);
document.addEventListener('pointerdown',e=>{if(open&&!e.target.closest('#fxp,.fxbtn'))close(false)},true);
addEventListener('resize',place);
addEventListener('scroll',place,{passive:true,capture:true});
FX.subscribe(s=>{
  sync();
  /* switching Mouse effects off: put back anything the cursor had moved */
  if(!s.mouse){
    document.querySelectorAll('.prod .tile,.dc .tile').forEach(t=>{t.style.transform=''});
    const h=document.getElementById('hero');
    if(h)['--mx','--my','--gx','--gy'].forEach(v=>h.style.removeProperty(v));
  }
});
const app=document.getElementById('app');
if(app)new MutationObserver(mark).observe(app,{childList:true});
})();
